sop:
@c1 syntax.clause form=fragment discourse="And" complement=$n1
@n1 syntax.nominal dependent="the" head="same"
@r1 syntax.relation marker="for" from=$n1 to=$n2
@n2 syntax.nominal dependent="all" head="tabs"

@c1 syntax.clause form=fragment discourse="sorry" complement=$n1 complement=$n2
@n1 syntax.nominal dependent="the" dependent="other" head="cat"
@n2 syntax.nominal dependent="this" head="time"

@c1 syntax.clause form=imperative verb="undo"
@r1 syntax.relation marker="if" from=$c1 to=$c2
@n1 syntax.nominal head="you"
@c2 syntax.clause form=declarative verb="can" subject=$n1
